<script setup lang="ts">
import {ref,nextTick} from 'vue';import type {Page,ResourceFile} from '../models';import {api} from '../api';import LessonDocument from './LessonDocument.vue';import {useTask} from '../useTask';import StatePanel from './StatePanel.vue';
const props=defineProps<{modelValue:string;courseId:string;disabled?:boolean}>(),emit=defineEmits<{ 'update:modelValue':[string] }>(),field=ref<HTMLTextAreaElement|null>(null),preview=ref(false),images=ref<ResourceFile[]>([]),dialog=ref(false);const {busy,error,run}=useTask();
function wrap(left:string,right=''){const t=field.value;if(!t)return;const a=t.selectionStart,b=t.selectionEnd;emit('update:modelValue',props.modelValue.slice(0,a)+left+props.modelValue.slice(a,b)+right+props.modelValue.slice(b));nextTick(()=>{t.focus();t.setSelectionRange(a+left.length,b+left.length);});}
function chooseImage(){dialog.value=true;run(async()=>{const p=await api<Page<ResourceFile>>('/api/courses/'+props.courseId+'/resources?size=100');images.value=p.items.filter(x=>x.mimeType.startsWith('image/'));if(p.total>100)throw Error('当前显示最近100份资源中的图片，可到资源书架整理后选择。');});}
function insertImage(image:ResourceFile){wrap('\n!['+image.title.replaceAll(']','')+'](resource:'+image.id+')\n');dialog.value=false;}
</script><template><section class="document-editor"><div class="editor-tools"><button type="button" :disabled="disabled" @click="wrap('# ')">标题</button><button type="button" :disabled="disabled" @click="wrap('**','**')">加粗</button><button type="button" :disabled="disabled" @click="wrap('*','*')">着重</button><button type="button" :disabled="disabled" @click="wrap('> ')">引文</button><button type="button" :disabled="disabled" @click="wrap('- ')">要点</button><button type="button" :disabled="disabled" @click="chooseImage">课程图片</button><button type="button" :aria-pressed="preview" @click="preview=!preview">{{preview?'继续编辑':'阅读预览'}}</button></div><textarea v-show="!preview" ref="field" :value="modelValue" @input="emit('update:modelValue',($event.target as HTMLTextAreaElement).value)" :disabled="disabled" maxlength="20000" rows="12" aria-label="排版讲义"/><LessonDocument v-if="preview" :content="modelValue"/><p class="field-hint">讲义支持标题、强调、引文、要点与本课程图片。链接可写作 [名称](https://网址)。保留原文区域用于逐字批注。</p></section><el-dialog v-model="dialog" title="选择课程图片" width="650px"><StatePanel :error="error" :busy="busy" @retry="chooseImage"/><div class="image-picker"><el-button v-for="i in images" :key="i.id" @click="insertImage(i)">{{i.title}}</el-button></div><p v-if="!images.length&&!busy">还没有图片。先在本课程资源书架上传PNG或JPG。</p></el-dialog></template>
